executor_test:
import assert from "node:assert/strict";
import { energy, has_signal } from "./out/answer.js";

for (const samples of [[], [0, -0], [-3, 4], [0.5, -0.25], [4096, 1, 1]]) {
  const xs = new Float32Array(samples);
  const expected = xs.reduce((sum, x) => Math.fround(sum + Math.fround(x * x)), 0);
  assert.equal(energy(xs), expected);
  assert.equal(has_signal(xs), expected > 0);
}
